        ["nihon-kojin-bango-input"] = new("html", "<Field\n  label=\"Individual Number / My Number (マイナンバー)\"\n  required\n>\n  <NihonKojinBangoInput\n    label=\"Individual Number / My Number (マイナンバー)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Twelve digits, issued to every resident of Japan since 2016. The twelfth digit is a check\n    digit: the first eleven digits are each multiplied by a position-dependent weight (6,5,4,3,2 for\n    positions 1-5; 7,6,5,4,3,2 for positions 6-11), summed, taken Modulus-11, and the remainder\n    subtracted from 11 (remainders of 0 or 1 both yield a check digit of 0).</Hint\n  >\n  <ErrorMessage>Please enter a valid Individual Number / My Number</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["nihon-kojin-bango-view"] = new("razor", "<NihonKojinBangoView Label=\"Nihon Kojin Bango\">...</NihonKojinBangoView>\n", new List<ExampleVariant> {  }),
        ["bharat-aadhaar-input"] = new("html", "<Field\n  label=\"Aadhaar (आधार)\"\n  required\n>\n  <BharatAadhaarInput\n    label=\"Aadhaar (आधार)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Twelve digits, the first of which is never 0 or 1. The twelfth digit is a check digit computed\n    with the Verhoeff algorithm, a checksum that detects every single-digit error and every\n    adjacent-digit transposition. Issued by the Unique Identification Authority of India\n    (UIDAI).</Hint\n  >\n  <ErrorMessage>Please enter a valid Aadhaar</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["bharat-aadhaar-view"] = new("html", "<SummaryList>\n  <SummaryListItem term=\"Aadhaar (आधार)\">\n    <BharatAadhaarView\n      label=\"Aadhaar (आधार)\"\n      value=\"{value}\"\n    />\n  </SummaryListItem>\n</SummaryList>\n", new List<ExampleVariant> {  }),
        ["yisrael-teudat-zehut-input"] = new("html", "<Field\n  label=\"Teudat Zehut (תעודת זהות)\"\n  required\n>\n  <YisraelTeudatZehutInput\n    label=\"Teudat Zehut (תעודת זהות)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Nine digits (left-padded with zeros when shorter), with the ninth a Luhn (Modulus-10) check\n    digit: digits alternate between weights of 1 and 2 from the left, any doubled product over 9 has\n    its own two digits summed, and the total must be a multiple of 10.</Hint\n  >\n  <ErrorMessage>Please enter a valid Teudat Zehut</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
