        ["zhongguo-jumin-shenfenzheng-haoma-view"] = new("razor", "<ZhongguoJuminShenfenzhengHaomaView Label=\"Zhongguo Jumin Shenfenzheng Haoma\">...</ZhongguoJuminShenfenzhengHaomaView>\n", new List<ExampleVariant> {  }),
