        ["rossiya-snils-view"] = new("html", "<SummaryList>\n  <SummaryListItem term=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\">\n    <RossiyaSnilsView\n      label=\"СНИЛС (Strakhovoy Nomer Individualnogo Litsevogo Scheta)\"\n      value=\"{value}\"\n    />\n  </SummaryListItem>\n</SummaryList>\n", new List<ExampleVariant> {  }),
        ["turkiye-tc-kimlik-numarasi-input"] = new("html", "<Field\n  label=\"T.C. Kimlik Numarası\"\n  required\n>\n  <TurkiyeTcKimlikNumarasiInput\n    label=\"T.C. Kimlik Numarası\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Eleven digits, the first never zero. The tenth digit is the units digit of ((sum of digits\n    1,3,5,7,9) × 7) plus ((sum of digits 2,4,6,8) × 9); the eleventh digit is the units digit of the\n    sum of the first ten digits. The eleventh digit is always even.</Hint\n  >\n  <ErrorMessage>Please enter a valid T.C. Kimlik Numarası</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
