        ["misr-al-raqm-al-qawmi-input"] = new("html", "<Field\n  label=\"الرقم القومي (Al-Raqm Al-Qawmi)\"\n  required\n>\n  <MisrAlRaqmAlQawmiInput\n    label=\"الرقم القومي (Al-Raqm Al-Qawmi)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Fourteen digits. The first digit encodes century of birth (2 for 1900-1999, 3 for 2000-2099);\n    the next six encode date of birth (YYMMDD); the next two encode governorate of\n    birth/registration; the next four are a serial number whose own parity encodes sex (odd male,\n    even female); the fourteenth digit is a check digit.</Hint\n  >\n  <ErrorMessage>Please enter a valid الرقم القومي</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["misr-al-raqm-al-qawmi-view"] = new("razor", "<MisrAlRaqmAlQawmiView Label=\"Misr Al Raqm Al Qawmi\">...</MisrAlRaqmAlQawmiView>\n", new List<ExampleVariant> {  }),
        ["taiwan-guomin-shenfenzheng-tongyi-bianhao-input"] = new("razor", "<TaiwanGuominShenfenzhengTongyiBianhaoInput Label=\"Taiwan Guomin Shenfenzheng Tongyi Bianhao\" />\n", new List<ExampleVariant> {  }),
        ["taiwan-guomin-shenfenzheng-tongyi-bianhao-view"] = new("razor", "<TaiwanGuominShenfenzhengTongyiBianhaoView Label=\"Taiwan Guomin Shenfenzheng Tongyi Bianhao\">...</TaiwanGuominShenfenzhengTongyiBianhaoView>\n", new List<ExampleVariant> {  }),
        ["hong-kong-identity-card-input"] = new("html", "<Field\n  label=\"Hong Kong Identity Card Number\"\n  required\n>\n  <HongKongIdentityCardInput\n    label=\"Hong Kong Identity Card Number\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >One or two letters, six digits and a check digit in parentheses, such as A123456(3). The check\n    digit is 0 to 9 or A. Each letter counts as A=10 to Z=35, and a single letter is preceded by a\n    space counted as 36; the eight values are multiplied by 9,8,7,6,5,4,3,2 and summed, and the\n    check digit is 11 minus the sum's Modulus-11 remainder (0 when the remainder is 0, and A when\n    the result is 10).</Hint\n  >\n  <ErrorMessage>Please enter a valid Hong Kong Identity Card Number</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["hong-kong-identity-card-view"] = new("razor", "<HongKongIdentityCardView Label=\"Hong Kong Identity Card\">...</HongKongIdentityCardView>\n", new List<ExampleVariant> {  }),
        ["iran-kod-e-melli-input"] = new("html", "<Field\n  label=\"National Code (Kod-e Melli)\"\n  required\n>\n  <IranKodEMelliInput\n    label=\"National Code (Kod-e Melli)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Ten digits whose last digit is a check digit. The first nine digits are multiplied by\n    10,9,8,7,6,5,4,3,2 and summed; with r the sum's Modulus-11 remainder, the check digit is r when\n    r is less than 2, otherwise 11 minus r. A number whose ten digits are all the same is never\n    valid.</Hint\n  >\n  <ErrorMessage>Please enter a valid National Code (Kod-e Melli)</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["iran-kod-e-melli-view"] = new("html", "<SummaryList>\n  <SummaryListItem term=\"National Code (Kod-e Melli)\">\n    <IranKodEMelliView\n      label=\"National Code (Kod-e Melli)\"\n      value=\"{value}\"\n    />\n  </SummaryListItem>\n</SummaryList>\n", new List<ExampleVariant> {  }),
        ["as-saudiyah-raqm-al-huwiyah-al-wataniyah-input"] = new("razor", "<AsSaudiyahRaqmAlHuwiyahAlWataniyahInput Label=\"As Saudiyah Raqm Al Huwiyah Al Wataniyah\" />\n", new List<ExampleVariant> {  }),
        ["as-saudiyah-raqm-al-huwiyah-al-wataniyah-view"] = new("razor", "<AsSaudiyahRaqmAlHuwiyahAlWataniyahView Label=\"As Saudiyah Raqm Al Huwiyah Al Wataniyah\">...</AsSaudiyahRaqmAlHuwiyahAlWataniyahView>\n", new List<ExampleVariant> {  }),
        ["malaysia-kad-pengenalan-input"] = new("html", "<Field\n  label=\"MyKad Number (NRIC)\"\n  required\n>\n  <MalaysiaKadPengenalanInput\n    label=\"MyKad Number (NRIC)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Twelve digits, usually written YYMMDD-PB-NNNG: the date of birth (year, month, day), a\n    two-digit code for the place of birth (a state or a country), and a four-digit serial whose last\n    digit is odd for a male and even for a female. There is no check digit.</Hint\n  >\n  <ErrorMessage>Please enter a valid MyKad Number (NRIC)</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["malaysia-kad-pengenalan-view"] = new("razor", "<MalaysiaKadPengenalanView Label=\"Malaysia Kad Pengenalan\">...</MalaysiaKadPengenalanView>\n", new List<ExampleVariant> {  }),
        ["viet-nam-can-cuoc-cong-dan-input"] = new("html", "<Field\n  label=\"Citizen Identification Number (CCCD)\"\n  required\n>\n  <VietNamCanCuocCongDanInput\n    label=\"Citizen Identification Number (CCCD)\"\n    value=\"{value}\"\n    required\n  />\n  <Hint\n    >Twelve digits: a three-digit code for the province or country of registration, one digit for\n    gender and century of birth (0 male and 1 female for the 1900s, 2 male and 3 female for the\n    2000s, and so on in pairs), the last two digits of the year of birth, and six random digits.\n    There is no published check digit.</Hint\n  >\n  <ErrorMessage>Please enter a valid Citizen Identification Number (CCCD)</ErrorMessage>\n</Field>\n", new List<ExampleVariant> {  }),
        ["viet-nam-can-cuoc-cong-dan-view"] = new("razor", "<VietNamCanCuocCongDanView Label=\"Viet Nam Can Cuoc Cong Dan\">...</VietNamCanCuocCongDanView>\n", new List<ExampleVariant> {  }),
